import asyncio
import contextlib
from typing import Any

from azure.cosmos.aio import CosmosClient

from semantic_kernel.data.const import DistanceFunction, IndexKind
from semantic_kernel.data.record_definition.vector_store_model_definition import VectorStoreRecordDefinition
from semantic_kernel.data.record_definition.vector_store_record_fields import VectorStoreRecordVectorField
from semantic_kernel.exceptions.memory_connector_exceptions import VectorStoreModelException

# The name of the property that will be used as the item id in Azure Cosmos DB NoSQL
COSMOS_ITEM_ID_PROPERTY_NAME = "id"


class CosmosClientWrapper(CosmosClient):
    """Wrapper to make sure the CosmosClient is closed when the object is deleted."""

    def __del__(self) -> None:
        """Close the connection.

        This is called when the object is deleted, used when the client is created internally.
        """
        with contextlib.suppress(Exception):
            asyncio.get_running_loop().create_task(self.close())


def _to_index_kind(index_kind: IndexKind | None) -> str:
    """Convert the index kind to the Azure Cosmos DB NoSQL index kind.

    Args:
        index_kind (IndexKind | None): The index kind.

    Returns:
        str: The Azure Cosmos DB NoSQL index kind.

    Raises:
        VectorStoreModelException: If the index kind is not supported by Azure Cosmos DB NoSQL.
    """
    if index_kind is None:
        # Use FLAT as the default index kind.
        return "flat"

    if index_kind == IndexKind.FLAT:
        return "flat"
    if index_kind == IndexKind.QUANTIZED_FLAT:
        return "quantizedFlat"
    if index_kind == IndexKind.DISK_ANN:
        return "diskANN"

    raise VectorStoreModelException(f"Index kind '{index_kind}' is not supported by Azure Cosmos DB NoSQL.")


def _to_distance_function(distance_function: DistanceFunction | None) -> str:
    """Convert the distance function to the Azure Cosmos DB NoSQL distance function.

    Args:
        distance_function (DistanceFunction | None): The distance function.

    Returns:
        str: The Azure Cosmos DB NoSQL distance function.

    Raises:
        VectorStoreModelException: If the distance function is not supported by Azure Cosmos DB NoSQL.
    """
    if distance_function is None:
        # Use cosine as the default distance function.
        return "cosine"

    if distance_function == DistanceFunction.COSINE_SIMILARITY:
        return "cosine"
    if distance_function == DistanceFunction.DOT_PROD:
        return "dotproduct"
    if distance_function == DistanceFunction.EUCLIDEAN_DISTANCE:
        return "euclidean"

    raise VectorStoreModelException(
        f"Distance function '{distance_function}' is not supported by Azure Cosmos DB NoSQL."
    )


def _to_datatype(property_type: str | None) -> str:
    """Convert the property type to the Azure Cosmos DB NoSQL data type.

    Args:
        property_type (str | None): The property type.

    Returns:
        str: The Azure Cosmos DB NoSQL data type.

    Raises:
        VectorStoreModelException: If the property type is not supported by Azure Cosmos DB NoSQL.
    """
    if property_type is None:
        # Use float32 as the default data type.
        return "float32"

    if property_type in ("float", "list[float]"):
        return "float32"
    if property_type in ("int", "list[int]"):
        return "int8"
    if property_type in ("uint8", "list[uint8]"):
        return "uint8"

    raise VectorStoreModelException(f"Property type '{property_type}' is not supported by Azure Cosmos DB NoSQL.")


def create_default_indexing_policy(data_model_definition: VectorStoreRecordDefinition) -> dict[str, Any]:
    """Create a default indexing policy for the Azure Cosmos DB NoSQL container.

    A default indexing policy is created based on the data model definition and has an automatic indexing policy.

    Args:
        data_model_definition (VectorStoreRecordDefinition): The definition of the data model.

    Returns:
        dict[str, Any]: The indexing policy.

    Raises:
        VectorStoreModelException: If a vector field does not specify an index kind that is
            supported by Azure Cosmos DB NoSQL.
    """
    indexing_policy: dict[str, Any] = {
        "automatic": True,
        "includedPaths": [
            {
                "path": "/*",
            }
        ],
        "excludedPaths": [
            {
                "path": '/"_etag"/?',
            }
        ],
        "vectorIndexes": [],
    }

    for field in data_model_definition.fields.values():
        if isinstance(field, VectorStoreRecordVectorField):
            indexing_policy["vectorIndexes"].append(
                {
                    "path": f"/{field.name}",
                    "type": _to_index_kind(field.index_kind),
                }
            )
            # For DiskANN and QuantizedFlat, the vector paths must be excluded from the standard index.
            if field.index_kind in [IndexKind.QUANTIZED_FLAT, IndexKind.DISK_ANN]:
                indexing_policy["excludedPaths"].append(
                    {
                        "path": f'/{field.name}/*',
                    }
                )

    return indexing_policy


def create_default_vector_embedding_policy(data_model_definition: VectorStoreRecordDefinition) -> dict[str, Any]:
    """Create a default vector embedding policy for the Azure Cosmos DB NoSQL container.

    A default vector embedding policy is created based on the data model definition.

    Args:
        data_model_definition (VectorStoreRecordDefinition): The definition of the data model.

    Returns:
        dict[str, Any]: The vector embedding policy.

    Raises:
        VectorStoreModelException: If a vector field does not specify a distance function or
            data type that is supported by Azure Cosmos DB NoSQL.
    """
    vector_embedding_policy: dict[str, Any] = {"vectorEmbeddings": []}

    for field in data_model_definition.fields.values():
        if isinstance(field, VectorStoreRecordVectorField):
            vector_embedding_policy["vectorEmbeddings"].append(
                {
                    "path": f"/{field.name}",
                    "dataType": _to_datatype(field.property_type),
                    "distanceFunction": _to_distance_function(field.distance_function),
                    "dimensions": field.dimensions,
                }
            )

    return vector_embedding_policy
